#ifndef ZOVUTILS_ACCOUNT_TERMINAL_BACKEND_H
#define ZOVUTILS_ACCOUNT_TERMINAL_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <unistd.h>
#include <termios.h>
#include <sys/ioctl.h>
#include <utmpx.h>
static inline int zov_users_run(int argc,char**argv){for(int i=0;i<argc;i++){if(!strcmp(argv[i],"--help")){puts("Usage: users [OPTION]... [FILE]\nPrint the user names of users currently logged in.\n  --help     display this help and exit\n  --version  output version information and exit");return 0;}if(!strcmp(argv[i],"--version")){puts("users (zovutils) 0.9.0");return 0;}fprintf(stderr,"users: extra operand '%s'\nTry 'users --help' for more information.\n",argv[i]);return 1;}setutxent();struct utmpx*u;int first=1;while((u=getutxent()))if(u->ut_type==USER_PROCESS){if(!first)putchar(' ');size_t n=0;while(n<sizeof(u->ut_user)&&u->ut_user[n])n++;fwrite(u->ut_user,1,n,stdout);first=0;}endutxent();if(!first)putchar('\n');return 0;}
static inline int zov_who_run(int argc,char**argv){int header=0,quick=0;for(int i=0;i<argc;i++){if(!strcmp(argv[i],"--help")){puts("Usage: who [OPTION]... [ FILE | ARG1 ARG2 ]\nPrint information about users who are currently logged in.\n  -H, --heading  print line of column headings\n  -q, --count    print only login names and number of users logged on\n      --help     display this help and exit\n      --version  output version information and exit");return 0;}if(!strcmp(argv[i],"--version")){puts("who (zovutils) 0.9.0");return 0;}if(!strcmp(argv[i],"-H")||!strcmp(argv[i],"--heading")){header=1;continue;}if(!strcmp(argv[i],"-q")||!strcmp(argv[i],"--count")){quick=1;continue;}if(argv[i][0]=='-'){fprintf(stderr,"who: unrecognized option '%s'\nTry 'who --help' for more information.\n",argv[i]);return 1;}}if(header&&!quick)puts("NAME     LINE         TIME         COMMENT");setutxent();struct utmpx*u;int count=0;while((u=getutxent()))if(u->ut_type==USER_PROCESS){char user[sizeof(u->ut_user)+1],line[sizeof(u->ut_line)+1];memcpy(user,u->ut_user,sizeof(u->ut_user));user[sizeof(u->ut_user)]=0;memcpy(line,u->ut_line,sizeof(u->ut_line));line[sizeof(u->ut_line)]=0;if(quick)printf("%s ",user);else{time_t t=(time_t)u->ut_tv.tv_sec;struct tm tmv;localtime_r(&t,&tmv);char b[64];strftime(b,sizeof b,"%Y-%m-%d %H:%M",&tmv);printf("%-8s %-12s %s\n",user,line,b);}count++;}endutxent();if(quick){putchar('\n');printf("# users=%d\n",count);}return 0;}
static inline int zov_stty_run(int argc,char**argv){int all=0,settings=0;for(int i=0;i<argc;i++){if(!strcmp(argv[i],"--help")){puts("Usage: stty [-F DEVICE | --file=DEVICE] [SETTING]...\n  -a, --all       print all current settings in human-readable form\n  -g, --save      print all current settings in a stty-readable form\n      --help      display this help and exit\n      --version   output version information and exit");return 0;}if(!strcmp(argv[i],"--version")){puts("stty (zovutils) 0.9.0");return 0;}if(!strcmp(argv[i],"-a")||!strcmp(argv[i],"--all")){all=1;continue;}if(!strcmp(argv[i],"-g")||!strcmp(argv[i],"--save")){settings=1;continue;}}struct termios t;if(tcgetattr(STDIN_FILENO,&t)<0){fprintf(stderr,"stty: 'standard input': %s\n",strerror(errno));return 1;}if(settings){for(size_t i=0;i<sizeof(t);i++)printf("%02x",((unsigned char*)&t)[i]);putchar('\n');return 0;}if(all){printf("speed %lu baud; line = 0;\n",(unsigned long)cfgetospeed(&t));return 0;}printf("speed %lu baud; line = 0;\n",(unsigned long)cfgetospeed(&t));return 0;}
#endif
